import { ChevronRight } from "lucide-react";
import { cn } from "@/lib/cn";

// A link row inside a grouped list card, the whole row one target.
// Trailing content is one of: page number, chevron. Names, meta and page are announced in reading order with commas.
// Hover underlines the name, pressed fills (sunken on a plain card, raised on a name-only card), focus ring is inside (conventions 4.1).

export type ListRowProps = {
  href: string;
  name: string;
  nameLang?: string;
  /** Secondary line, for example "ingredients matched: coconut". Not rendered when empty. */
  meta?: string;
  /** Page digits as given ("44"). Shown "p. 44", announced "page 44". When present it replaces the chevron. */
  page?: string;
  /** Which card the row sits in: decides the pressed fill and the chevron colour. */
  ground?: "plain" | "name-only";
  onClick?: React.MouseEventHandler<HTMLAnchorElement>;
};

// inline, not absolute: keeps the hidden text in the accessible name with ordinary spacing
const hidden = "[clip-path:inset(50%)]";

export function ListRow({ href, name, nameLang, meta, page, ground = "plain", onClick }: ListRowProps) {
  const onSunken = ground === "name-only";
  const hasMeta = !!meta && meta.trim() !== "";
  return (
    <a
      href={href}
      onClick={onClick}
      className={cn(
        "group flex min-h-control items-center justify-between gap-gap-md px-inset-md py-3 font-body leading-normal no-underline",
        onSunken ? "active:bg-surface-raised" : "active:bg-surface-sunken",
        "focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring-inside focus-visible:outline-focus-ring",
      )}
    >
      <span className="min-w-0 flex-1">
        <span lang={nameLang} className="block text-ui-body font-medium text-text [overflow-wrap:anywhere] group-hover:underline">
          {name}
          {(hasMeta || page) && <span className={hidden}>,</span>}
        </span>
        {" "}
        {hasMeta && (
          <span className="block text-ui-floor font-regular text-text-muted [overflow-wrap:anywhere]">
            {meta}
            {page && <span className={hidden}>,</span>}
          </span>
        )}
        {hasMeta && " "}
      </span>
      {" "}
      {page ? (
        <span className="block shrink-0 text-ui-floor font-regular text-text-muted">
          <span aria-hidden="true">p.</span>
          <span className="sr-only">page</span> {page}
        </span>
      ) : (
        <ChevronRight
          aria-hidden="true"
          className={cn("size-icon-lg shrink-0 group-active:text-text-muted", onSunken ? "text-text-muted" : "text-text-subtle")}
        />
      )}
    </a>
  );
}
